'use client';

import { useState } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import {
  hold,
  PRESS_LEAD_MS,
  pressedQuietOf,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import {
  restStyleOf,
  RING_SPEC,
  stillStyleOf,
  type RingSpec,
  type SoundRingSize,
} from './_parts/ring-geometry';
import { usePlayWhileSeen } from './_parts/use-play-while-seen';
import { useRingMotion } from './_parts/use-ring-motion';

export type { SoundRingSize } from './_parts/ring-geometry';

function accessibilityOf(label: string | undefined) {
  if (label === undefined) {
    return { 'aria-hidden': true } as const;
  }
  return { role: 'img', 'aria-label': label } as const;
}

function barStyleOf(index: number, spec: RingSpec, showsStill: boolean) {
  if (showsStill) {
    return stillStyleOf(index, spec);
  }
  return restStyleOf(index, spec);
}

export type SoundRingProps = {
  /** While false the ring is quiet: its bars rest and nothing runs. */
  isActive: boolean;
  /** The live level of the sound, between 0 and 1, read about eight times a second: the louder it is, the faster the peak turns. Left out, a simulated voice drives the ring. */
  level?: () => number;
  /** `sm` is 20px and sits beside a label, `md` is 40px and fits a button, `lg` is 96px and stands alone. */
  size?: SoundRingSize;
  /** Names the ring for screen readers when it stands alone. Left out, it is decorative. */
  label?: string;
  className?: string;
};

export function SoundRing({
  isActive,
  level,
  size = 'md',
  label,
  className,
}: SoundRingProps) {
  const spec = RING_SPEC[size];
  const { ref, isOnScreen, isStill } = usePlayWhileSeen<HTMLSpanElement>();
  const showsStill = isActive && isStill;
  const accessibility = accessibilityOf(label);
  const indexes = Array.from({ length: spec.bars }, (_, index) => index);

  useRingMotion(ref, { spec, isActive, isStill, isOnScreen, level });

  return (
    <span
      ref={ref}
      {...accessibility}
      style={{ width: spec.px, height: spec.px }}
      className={cn('text-primary relative inline-block shrink-0', className)}
    >
      {indexes.map((index) => (
        <span
          key={index}
          data-bar=''
          style={barStyleOf(index, spec, showsStill)}
          className='absolute bottom-1/2 left-1/2 origin-bottom rounded-full bg-current transition-[transform,opacity] duration-300 ease-(--ease-out-strong)'
        />
      ))}
    </span>
  );
}

const STATE_WORDS = ['Idle', 'Listening'];

function stateWordOf(isActive: boolean) {
  if (isActive) {
    return 'Listening';
  }
  return 'Idle';
}

export default function Voice05() {
  const [isActive, setIsActive] = useState(true);
  const { pressed, press } = usePress<'listen'>();
  const stateWord = stateWordOf(isActive);

  function toggle() {
    setIsActive((current) => !current);
  }

  function goQuiet() {
    setIsActive(false);
  }

  function goActive() {
    setIsActive(true);
  }

  const steps: AutoplayStep[] = [
    { after: 5200, run: () => press('listen') },
    { after: PRESS_LEAD_MS, run: goQuiet },
    { after: 2200, run: () => press('listen') },
    { after: PRESS_LEAD_MS, run: goActive },
    { after: 2600, run: hold },
  ];
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: 600,
    onReset: goActive,
  });

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='flex w-full max-w-[22rem] flex-col items-center gap-4'
    >
      <div className='bg-card hairline-ring ring-border flex w-full flex-col items-center gap-6 rounded-xl px-4 py-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <SoundRing size='lg' isActive={isActive} label={stateWord} />
        <div className='flex w-full items-center justify-between gap-3'>
          <p className='flex min-w-0 items-center gap-2 text-[13px] font-medium'>
            <SoundRing size='sm' isActive={isActive} />
            <WordRoll text={stateWord} labels={STATE_WORDS} />
          </p>
          <Button
            type='button'
            variant='outline'
            aria-label='Listen'
            aria-pressed={isActive}
            onClick={toggle}
            className={cn('size-14 p-0', pressedQuietOf(pressed === 'listen'))}
          >
            <SoundRing size='md' isActive={isActive} />
          </Button>
        </div>
      </div>
      <LiveRegion message={spokenUnless(isAutoplaying, stateWord)} />
    </div>
  );
}

const ATTACK_S = 0.04;

const RELEASE_S = 0.2;

/** Rises fast and falls slowly, whatever the frame rate. */
export function followLevel(current: number, target: number, step: number) {
  const gap = target - current;
  const isRising = gap > 0;
  let constant = RELEASE_S;
  if (isRising) {
    constant = ATTACK_S;
  }
  const amount = 1 - Math.exp(-step / constant);
  return current + gap * amount;
}

import type { CSSProperties } from 'react';

export type SoundRingSize = 'sm' | 'md' | 'lg';

export type RingSpec = {
  px: number;
  bars: number;
  inner: number;
  length: number;
  width: number;
};

/** A bar at full scale ends at the edge of the square: inner plus length is half of it. */
export const RING_SPEC: Record<SoundRingSize, RingSpec> = {
  sm: { px: 20, bars: 24, inner: 6, length: 4, width: 1 },
  md: { px: 40, bars: 24, inner: 12, length: 8, width: 2 },
  lg: { px: 96, bars: 32, inner: 28.8, length: 19.2, width: 4 },
};

/** One turn of the peak round the ring at its base speed: the level makes it shorter or longer. */
export const LAP_MS = 1800;

const REST_SCALE = 0.22;

const REST_OPACITY = 0.32;

/** A peak is a smooth hump that falls to nothing this many bars away on each side. */
const REACH_BARS = 5;

const PEAK_LIFT = 0.88;

const ECHO_LIFT = 0.36;

/** The echo comes half a lap after the peak, straight across the ring. */
const ECHO_SHARE_OF_LAP = 0.5;

/** Under reduced motion the peak stands this share of the ring clockwise from the top. */
const STILL_PEAK_SHARE = 0.15;

function wrappedGap(first: number, second: number, bars: number) {
  const difference = Math.abs(first - second);
  const gap = difference % bars;
  const other = bars - gap;
  return Math.min(gap, other);
}

function humpOf(distance: number) {
  if (distance >= REACH_BARS) {
    return 0;
  }
  const share = distance / REACH_BARS;
  const angle = Math.PI * share;
  const cosine = Math.cos(angle);
  const lifted = 1 + cosine;
  return lifted / 2;
}

/**
 * How high a bar stands, from 0 at rest to 1 at full height, at a place of its lap counted in bars.
 * A lap starts at rest, so a bar that has not begun its lap yet is already in the right pose.
 */
function liftAt(place: number, bars: number) {
  const echoOffset = bars * ECHO_SHARE_OF_LAP;
  const echoCenter = REACH_BARS + echoOffset;
  const peakGap = wrappedGap(place, REACH_BARS, bars);
  const echoGap = wrappedGap(place, echoCenter, bars);
  const peakHump = humpOf(peakGap);
  const echoHump = humpOf(echoGap);
  const peak = PEAK_LIFT * peakHump;
  const echo = ECHO_LIFT * echoHump;
  const total = peak + echo;
  return Math.min(1, total);
}

function roundedTo(value: number, digits: number) {
  const factor = 10 ** digits;
  const scaled = value * factor;
  const rounded = Math.round(scaled);
  return rounded / factor;
}

function liftedFrom(rest: number, lift: number) {
  const span = 1 - rest;
  const climb = span * lift;
  return rest + climb;
}

type BarPose = {
  transform: string;
  opacity: number;
};

function poseOf(spec: RingSpec, lift: number): BarPose {
  const scale = liftedFrom(REST_SCALE, lift);
  const opacity = liftedFrom(REST_OPACITY, lift);
  const scaleText = roundedTo(scale, 3);
  const shownOpacity = roundedTo(opacity, 3);
  const transform = `translateY(-${spec.inner}px) scaleY(${scaleText})`;
  return { transform, opacity: shownOpacity };
}

function lapLiftsOf(bars: number) {
  const lifts: number[] = [];
  for (let knot = 0; knot <= bars; knot += 1) {
    lifts.push(liftAt(knot, bars));
  }
  return lifts;
}

function isNeededKnot(lifts: number[], knot: number) {
  const isEdge = knot === 0 || knot === lifts.length - 1;
  const isLifted = lifts[knot] > 0;
  const followsLift = lifts[knot - 1] > 0;
  const precedesLift = lifts[knot + 1] > 0;
  return isEdge || isLifted || followsLift || precedesLift;
}

/**
 * The lap of one bar, shared by every bar of the ring: a knot per bar along the lap, where the
 * stretches of rest between the two humps need no knot of their own.
 */
export function lapKeyframesOf(spec: RingSpec) {
  const lifts = lapLiftsOf(spec.bars);
  const keyframes: Keyframe[] = [];
  for (let knot = 0; knot < lifts.length; knot += 1) {
    if (!isNeededKnot(lifts, knot)) {
      continue;
    }
    const pose = poseOf(spec, lifts[knot]);
    const offset = knot / spec.bars;
    keyframes.push({ offset, ...pose });
  }
  return keyframes;
}

/** Each bar starts its lap a bar later than the one before it, so the peak turns clockwise. */
export function lapDelayOf(index: number, bars: number) {
  const share = index / bars;
  return share * LAP_MS;
}

function barStyleOf(
  index: number,
  spec: RingSpec,
  lift: number
): CSSProperties {
  const share = index / spec.bars;
  const degrees = share * 360;
  const halfWidth = spec.width / 2;
  const pose = poseOf(spec, lift);
  return {
    width: spec.width,
    height: spec.length,
    marginLeft: -halfWidth,
    rotate: `${degrees}deg`,
    transform: pose.transform,
    opacity: pose.opacity,
  };
}

export function restStyleOf(index: number, spec: RingSpec) {
  return barStyleOf(index, spec, 0);
}

function stillLiftOf(index: number, bars: number) {
  const peakBar = STILL_PEAK_SHARE * bars;
  const fromPeak = index - peakBar;
  const place = REACH_BARS - fromPeak;
  return liftAt(place, bars);
}

/** The pose of a bar under reduced motion: the ring stands on one frame of its lap and stays there. */
export function stillStyleOf(index: number, spec: RingSpec) {
  const lift = stillLiftOf(index, spec.bars);
  return barStyleOf(index, spec, lift);
}

import {
  LAP_MS,
  lapDelayOf,
  lapKeyframesOf,
  type RingSpec,
} from './ring-geometry';
import { BASE_PACE, rateOf } from './ring-pace';

const LAND_MS = 300;

const LAND_EASING = 'cubic-bezier(0.23, 1, 0.32, 1)';

const LAND_TIMING: KeyframeAnimationOptions = {
  duration: LAND_MS,
  easing: LAND_EASING,
};

export type RingLoops = {
  animations: Animation[];
  pace: number;
};

function barsOf(root: HTMLElement) {
  return Array.from(root.querySelectorAll('[data-bar]'));
}

/**
 * One animation per bar on transform and opacity, all with the same keyframes: the browser's own
 * animation engine plays them, so the page does no work per frame.
 */
export function startRingLoops(root: HTMLElement, spec: RingSpec): RingLoops {
  const keyframes = lapKeyframesOf(spec);
  const bars = barsOf(root);
  const animations = bars.map((bar, index) => {
    const delay = lapDelayOf(index, spec.bars);
    return bar.animate(keyframes, {
      duration: LAP_MS,
      delay,
      iterations: Infinity,
    });
  });
  return { animations, pace: BASE_PACE };
}

/** Every bar changes speed in the same task, so the peak keeps its shape while the lap gets faster or slower. */
export function setLapPace(loops: RingLoops, pace: number) {
  if (pace === loops.pace) {
    return;
  }
  loops.pace = pace;
  const rate = rateOf(pace);
  for (const animation of loops.animations) {
    animation.updatePlaybackRate(rate);
  }
}

/**
 * A cancelled animation is left alone: playing or even pausing it would bring it back and hold its
 * bar in a pose its ring has already left.
 */
function isCancelled(animation: Animation) {
  return animation.playState === 'idle';
}

export function playAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    if (!isCancelled(animation)) {
      animation.play();
    }
  }
}

export function pauseAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    if (!isCancelled(animation)) {
      animation.pause();
    }
  }
}

export function cancelAll(animations: readonly Animation[]) {
  for (const animation of animations) {
    animation.cancel();
  }
}

type Pose = {
  transform: string;
  opacity: string;
};

type Landing = {
  target: Element;
  shown: Pose;
};

function targetOf(animation: Animation) {
  const effect = animation.effect;
  if (effect instanceof KeyframeEffect) {
    return effect.target;
  }
  return null;
}

function poseOf(element: Element): Pose {
  const styles = getComputedStyle(element);
  return { transform: styles.transform, opacity: styles.opacity };
}

function landingsOf(animations: readonly Animation[]) {
  const landings: Landing[] = [];
  for (const animation of animations) {
    const target = targetOf(animation);
    if (target?.isConnected) {
      const shown = poseOf(target);
      landings.push({ target, shown });
    }
  }
  return landings;
}

/**
 * From the pose its lap left it in, each bar glides back to its resting style, then lets go. The
 * poses are read together, then the laps are dropped, then the resting poses are read together,
 * so the page restyles twice whatever the number of bars.
 */
export function landAll(animations: readonly Animation[]) {
  const landings = landingsOf(animations);
  cancelAll(animations);
  const rests = landings.map((landing) => poseOf(landing.target));
  landings.forEach((landing, index) => {
    const keyframes = [landing.shown, rests[index]];
    landing.target.animate(keyframes, LAND_TIMING);
  });
}

import { speechLevelAt } from '@/registry/ndeko/lib/speech-envelope';

/** The lap is never retimed more often than this: every retiming asks the browser to restart each bar's animation. */
export const POLL_MS = 125;

export const POLL_S = POLL_MS / 1000;

/** Until the first reading the lap runs at its base speed. */
export const BASE_PACE = 10;

export const START_LEVEL = 0.3;

const TENTHS = 10;

/** A pace counts tenths of the base speed: 0.6x when quiet, 2.2x at full level. */
const SLOWEST_PACE = 6;

const FASTEST_PACE = 22;

const HEARD_SEED = 0.9;

const WINDOW_SAMPLES = 4;

const SIMULATED_GAIN = 1.3;

export function rateOf(pace: number) {
  return pace / TENTHS;
}

export function paceOf(level: number) {
  const span = FASTEST_PACE - SLOWEST_PACE;
  const climb = span * level;
  const exact = SLOWEST_PACE + climb;
  return Math.round(exact);
}

function boundedLevelOf(value: number) {
  if (!Number.isFinite(value)) {
    return 0;
  }
  const atLeastZero = Math.max(0, value);
  return Math.min(1, atLeastZero);
}

/** The mean over the last poll: a syllable lasts about as long as one poll, so a single sample would catch it at random. */
function simulatedLevelAt(elapsed: number) {
  let total = 0;
  for (let sample = 0; sample < WINDOW_SAMPLES; sample += 1) {
    const share = sample / WINDOW_SAMPLES;
    const age = share * POLL_MS;
    const time = elapsed - age;
    total += speechLevelAt(time, HEARD_SEED);
  }
  const mean = total / WINDOW_SAMPLES;
  const gained = mean * SIMULATED_GAIN;
  return Math.min(1, gained);
}

export function heardLevelOf(
  provider: (() => number) | undefined,
  elapsed: number
) {
  if (provider) {
    const heard = provider();
    return boundedLevelOf(heard);
  }
  return simulatedLevelAt(elapsed);
}

'use client';

import { useInView } from 'motion/react';
import { useRef } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const IN_VIEW_SHARE = 0.2;

/**
 * A voice indicator moves only while someone can see it: on screen, in the tab that is shown,
 * without reduced motion. `isStill` asks for the still frame instead, and `isOnScreen` is for the
 * clocks that keep a session going under reduced motion.
 */
export function usePlayWhileSeen<Element extends HTMLElement = HTMLElement>() {
  const ref = useRef<Element>(null);
  const isInView = useInView(ref, { amount: IN_VIEW_SHARE });
  const isTabVisible = useDocumentVisible();
  const isStill = usePrefersReducedMotion();
  const isOnScreen = isInView && isTabVisible;
  const isPlaying = isOnScreen && !isStill;

  return { ref, isOnScreen, isPlaying, isStill };
}

'use client';

import { useEffect, useEffectEvent, useRef, type RefObject } from 'react';

import { followLevel } from './level';
import type { RingSpec } from './ring-geometry';
import {
  cancelAll,
  landAll,
  pauseAll,
  playAll,
  setLapPace,
  startRingLoops,
  type RingLoops,
} from './ring-loops';
import {
  heardLevelOf,
  paceOf,
  POLL_MS,
  POLL_S,
  START_LEVEL,
} from './ring-pace';

type RingMotionOptions = {
  spec: RingSpec;
  isActive: boolean;
  isStill: boolean;
  isOnScreen: boolean;
  level: (() => number) | undefined;
};

/**
 * The animations of a ring are made when it becomes active and paused whenever it is not seen, so
 * they ask for no frame off screen or in a hidden tab. While it is seen a timer reads the level a
 * few times a second and retimes the lap. When the ring goes quiet each bar glides back to rest and
 * the animations are gone. Under reduced motion none are made.
 */
export function useRingMotion(
  rootRef: RefObject<HTMLElement | null>,
  { spec, isActive, isStill, isOnScreen, level }: RingMotionOptions
) {
  const running = useRef<RingLoops | null>(null);
  const canLoop = isActive && !isStill;
  const isLive = canLoop && isOnScreen;

  const levelAt = useEffectEvent((elapsed: number) => {
    return heardLevelOf(level, elapsed);
  });

  /** Stopped by the reduced motion setting, a ring goes straight to rest instead of gliding there. */
  const finish = useEffectEvent(
    (animations: Animation[], root: HTMLElement) => {
      const canGlide = root.isConnected && !isStill;
      if (canGlide) {
        landAll(animations);
        return;
      }
      cancelAll(animations);
    }
  );

  useEffect(() => {
    const root = rootRef.current;
    if (!root || !canLoop) {
      return;
    }
    const loops = startRingLoops(root, spec);
    pauseAll(loops.animations);
    running.current = loops;
    return () => {
      running.current = null;
      finish(loops.animations, root);
    };
  }, [rootRef, canLoop, spec]);

  useEffect(() => {
    const loops = running.current;
    if (!loops || !isLive) {
      return;
    }
    playAll(loops.animations);
    return () => pauseAll(loops.animations);
  }, [canLoop, isLive, spec]);

  useEffect(() => {
    if (!isLive) {
      return;
    }
    const startedAt = performance.now();
    let followed = START_LEVEL;

    function retime() {
      const loops = running.current;
      if (!loops) {
        return;
      }
      const now = performance.now();
      const elapsed = now - startedAt;
      const heard = levelAt(elapsed);
      followed = followLevel(followed, heard, POLL_S);
      const pace = paceOf(followed);
      setLapPace(loops, pace);
    }

    const timer = setInterval(retime, POLL_MS);
    return () => clearInterval(timer);
  }, [isLive]);
}
